(() => {
  const products = Products.data.data || [];
  const selected = chkStatus.selectedValues || [];

  // Nothing selected or both selected = show all
  if (
    selected.length === 0 ||
    selected.length === 2
  ) {
    return products;
  }

  if (selected.includes("active")) {
    return products.filter(p => p.is_active);
  }

  if (selected.includes("inactive")) {
    return products.filter(p => !p.is_active);
  }

  return products;
})()
}}

